113		if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') {
114			return 0
115		}
116		if len(rest) > 1 && strings.IndexByte("-+~", rest[1]) < 0 {
117			return 0
118		}
119		return c | 0x20
120	}
121	
122	// CompareVersions orders two versions numerically, returning -1, 0 or 1 and
123	// true, or false when either has no leading number — a distro epoch such as
124	// "1:1.1.1n", a commit hash, a name. A missing component reads as zero
125	// (1.2 == 1.2.0), and a version with a "-" suffix sorts below the bare one
126	// (1.2.3-rc1 < 1.2.3). A single release letter right after the digits is an
127	// order too, as OpenSSL writes it: 1.1.1 < 1.1.1l < 1.1.1w. The result is a
128	// lenient ordering, not semver.
129	func CompareVersions(a, b string) (int, bool) {
130		an, ar, aok := parseVersion(a)
131		bn, br, bok := parseVersion(b)
132		if !aok || !bok {
133			return 0, false
134		}
135		for i := 0; i < max(len(an), len(bn)); i++ {
136			var x, y int
137			if i < len(an) {
138				x = an[i]
139			}
140			if i < len(bn) {
141				y = bn[i]
142			}
143			if x != y {
144				if x < y {
145					return -1, true
146				}
147				return 1, true
148			}
149		}
150		if al, bl := suffixLetter(ar), suffixLetter(br); al != bl {
151			if al < bl {
152				return -1, true
153			}
154			return 1, true
155		}
156		aPre, bPre := strings.HasPrefix(ar, "-"), strings.HasPrefix(br, "-")
157		switch {
158		case aPre && !bPre:
159			return -1, true
160		case !aPre && bPre:
161			return 1, true
162		}
163		return 0, true
164	}
165	
166	// PickFixed chooses the version to move to from Trivy's FixedVersion, which
167	// lists one fixed version per maintained branch ("1.2.4, 1.3.1"). It takes the
168	// lowest one on the installed version's major line, which is the smallest
169	// change that clears the CVE, and falls back to the lowest overall when no
170	// branch shares the major. A single value is returned as is, comparable or
171	// not; several that cannot be compared give "", because picking one of them
172	// would be a guess.
173	func PickFixed(installed, fixedIn string) string {
174		var options []string
175		for _, v := range strings.Split(fixedIn, ",") {
176			if v = strings.TrimSpace(v); v != "" {
177				options = append(options, v)
178			}
179		}
180		switch len(options) {
181		case 0:
182			return ""
183		case 1:
184			return options[0]
185		}
186	
187		instNums, _, instOK := parseVersion(installed)
188		best, bestSameMajor := "", false
189		for _, opt := range options {
190			nums, _, ok := parseVersion(opt)
191			if !ok {
192				return ""
193			}
194			same := instOK && len(instNums) > 0 && nums[0] == instNums[0]
195			switch {
196			case best == "":
197			case same && !bestSameMajor:
198			case same == bestSameMajor:
199				if c, _ := CompareVersions(opt, best); c >= 0 {
200					continue
201				}
202			default:
203				continue
204			}
205			best, bestSameMajor = opt, same
206		}
207		return best
208	}
209	
210	// fixInstruction is the sentence a finding carries when its ecosystem has no
211	// known command. The text is stored in the scan cache, so it must not change.
212	func fixInstruction(pkg, target string) string {
213		return fmt.Sprintf("Update %s to %s", pkg, target)
214	}
215	
216	// IsFixInstruction reports whether f.FixCommand is the sentence fixInstruction
217	// writes for f's package rather than a command the user can run. A caller shows
218	// a command as "Run: ..." and a sentence as plain text.
219	func IsFixInstruction(f Finding) bool {
220		if f.PkgName == "" {
221			return false
222		}
223		prefix := fixInstruction(f.PkgName, "")
224		return strings.HasPrefix(f.FixCommand, prefix) && len(f.FixCommand) > len(prefix)
225	}
