20	// FixCommand returns the command that moves pkg to version in the given
21	// ecosystem (Trivy's Result.Type), and false when no command is known — an
22	// ecosystem outside the table, or nothing to move to. It never invents one:
23	// "no command" is a real answer, and the caller shows the target version alone.
24	//
25	// pkg and version come from a scan, so from whoever published the package: a
26	// command is built only from values that pass plainToken, and none otherwise.
27	// The command is meant to be pasted into a shell.
28	func FixCommand(ecosystem, pkg, version string) (string, bool) {
29		if !plainToken(pkg) || !plainToken(version) {
30			return "", false
31		}
32		switch ecosystem {
33		case "gomod", "gobinary":
34			return "go get " + pkg + "@v" + strings.TrimPrefix(version, "v"), true
35		case "npm", "node-pkg":
36			return "npm install " + pkg + "@" + version, true
37		case "yarn":
38			return "yarn add " + pkg + "@" + version, true
39		case "pnpm":
40			return "pnpm add " + pkg + "@" + version, true
41		case "pip", "pipenv", "python-pkg":
42			return "pip install " + pkg + "==" + version, true
43		case "poetry":
44			return "poetry add " + pkg + "==" + version, true
45		case "cargo", "rust-binary":
46			return "cargo update -p " + pkg + " --precise " + version, true
47		case "alpine":
48			return "apk upgrade " + pkg, true
49		case "debian", "ubuntu":
50			return "apt-get install --only-upgrade " + pkg, true
51		}
52		return "", false
53	}
