55	// plainToken reports whether s is a package name or a version a command can be
56	// built from: one or more of A-Z a-z 0-9 @ / . _ + ~ : = ^ , -, and not an
57	// option (no leading "-"). That is every spelling the ecosystems above produce
58	// (scoped names, Go module paths, Debian epochs and revisions, "+build"
59	// metadata); a space, a quote or any shell metacharacter is not one of them.
60	func plainToken(s string) bool {
61		if s == "" || s[0] == '-' {
62			return false
63		}
64		for i := 0; i < len(s); i++ {
65			c := s[i]
66			switch {
67			case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
68			case strings.IndexByte("@/._+~:=^,-", c) >= 0:
69			default:
70				return false
71			}
72		}
73		return true
74	}
75	
76	// versionNumbers matches the leading dotted number of a version, ignoring a
77	// "v" prefix. What follows (a pre-release, a distro revision such as -r0 or
78	// +deb11u3) is not part of the comparison, except as noted in CompareVersions.
79	var versionNumbers = regexp.MustCompile(`^v?(\d+(?:\.\d+)*)`)
80	
81	// parseVersion returns the dotted numbers of v and the text after them.
82	func parseVersion(v string) (nums []int, rest string, ok bool) {
83		v = strings.TrimSpace(v)
84		m := versionNumbers.FindStringSubmatch(v)
85		if m == nil {
86			return nil, "", false
87		}
88		for _, part := range strings.Split(m[1], ".") {
89			n, err := strconv.Atoi(part)
90			if err != nil {
91				return nil, "", false
92			}
93			nums = append(nums, n)
94		}
95		rest = v[len(m[0]):]
96		if strings.HasPrefix(rest, ":") {
97			// A Debian epoch ("1:1.1.1n"): the number before the colon outranks
98			// everything after it, so reading it as a version would misorder.
99			return nil, "", false
100		}
101		return nums, rest, true
102	}
103	
104	// suffixLetter returns the lowercase letter that directly follows the digits of
105	// a version when it is a release letter (OpenSSL style: 1.1.1w), 0 otherwise.
