19	// DEVDESK-754 (SC1): "Group by fix" on the CVE tab. `g` swaps the body of the
20	// results between the findings table and one row per cause (the grouped list);
21	// enter on a group opens StateGroup, the findings of that group, and enter there
22	// opens the same detail as from the flat table. The findings table is never
23	// rebuilt by any of it, so its filter, sort, query and cursor are what the user
24	// left. Groups are derived from the result on screen and never stored as done.
25	
26	// groupToggleKey switches the results between the findings table and the grouped
27	// list. A lowercase letter is a display toggle, declared in keymap.localToggles.
28	const groupToggleKey = "g"
29	
30	// Why `g`, `Y` and the keys that act on one finding are greyed in the grouped
31	// list (Rule 130).
32	const (
33		reasonGroupNotHere    = "Group by fix covers the CVE tab"
34		reasonNothingToGroup  = "No vulnerability to group"
35		reasonOpenTheGroup    = "Open the group to act on one finding"
36		reasonNoGroupSelected = "No group selected"
37		reasonNoGroupCommand  = "This group has no command to run"
38		reasonGroupHasNoFix   = "No fix is published for this group"
39		reasonCopyNeedsGroup  = "Copy the command from a group (g), or from a finding's detail"
40	)
41	
42	// The two words of the toggle, named for the display it switches to.
43	const (
44		labelGroupByFix    = "Group by fix"
45		labelListByFinding = "List by finding"
46	)
47	
48	// isGrouped reports whether the active tab shows the grouped list.
49	func (m Model) isGrouped() bool { return m.groupedTabs[m.activeTab] }
50	
51	// canGroup says whether `g` applies here. In the grouped list it always does,
52	// even with no group left: it is the way back.
53	func (m Model) canGroup() shortcut.Availability {
54		switch {
55		case m.activeTab != TabCVE:
56			return shortcut.Unavailable(reasonGroupNotHere)
57		case m.isGrouped():
58			return shortcut.Availability{}
59		case !m.hasVulnerability():
60			return shortcut.Unavailable(reasonNothingToGroup)
61		}
62		return shortcut.Availability{}
63	}
64	
65	// hasVulnerability says whether the result holds a CVE at all, whatever the
66	// filters hide: a search that matches none does not make them vanish.
67	func (m Model) hasVulnerability() bool {
68		if m.result == nil {
69			return false
70		}
71		for _, f := range m.result.Findings {
72			if scan.Categorize(f) == scan.CategoryVulnerability {
73				return true
74			}
75		}
76		return false
77	}
78	
79	// toggleGroup switches the CVE tab between the findings table and the grouped
80	// list, or says why it cannot (Rule 130). Neither way rebuilds the findings
81	// table: going in selects the group of the selected finding, coming out puts the
82	// findings cursor on the first visible member of the group under the cursor.
83	func (m Model) toggleGroup() (tea.Model, tea.Cmd) {
84		if a := m.canGroup(); !a.Enabled() {
85			return m, m.footer.Warn(a.Reason)
86		}
87		if m.isGrouped() {
88			m.leaveGroupedList()
89			return m, nil
90		}
91		m.enterGroupedList()
92		return m, nil
93	}
94	
95	// enterGroupedList builds the groups from the result and puts the cursor on the
96	// group of the selected finding.
97	func (m *Model) enterGroupedList() {
98		m.groupedTabs[TabCVE] = true
99		m.groupsAll = cveGroups(m.result.Findings)
100		m.groups.SetItems(visibleGroups(m.groupsAll, m.findingsTable.Visible()))
101		m.groups.GotoTop()
102		m.groups.Remeasure()
103		if f, ok := m.findingsTable.Selected(); ok {
104			if i := groupIndexOf(m.groups.Visible(), f); i >= 0 {
105				m.groups.SetCursor(i)
106			}
107		}
108	}
109	
110	// leaveGroupedList shows the findings table again, its cursor on the first
111	// visible member of the group that was selected.
112	func (m *Model) leaveGroupedList() {
113		var group *fixGroup
114		if g, ok := m.groups.Selected(); ok {
115			group = &g
116		}
117		var prev *scan.Finding
118		if f, ok := m.findingsTable.Selected(); ok {
119			prev = &f
120		}
121		m.groupedTabs[TabCVE] = false
122		if i := nearestFinding(m.findingsTable.Visible(), group, prev, m.findingsTable.Cursor()); i >= 0 {
123			m.findingsTable.SetCursor(i)
124		}
125	}
126	
127	// groupsFollowResult rebuilds the groups after the result changed. Nothing is
128	// built while the CVE tab is flat: the next `g` builds them from the result then
129	// on screen.
130	func (m *Model) groupsFollowResult() {
131		m.groupsAll = nil
132		if m.groupedTabs[TabCVE] && m.result != nil {
133			m.groupsAll = cveGroups(m.result.Findings)
134		}
135		m.refreshGroups()
136	}
137	
138	// refreshGroups lists the groups that hold a finding the findings table shows,
139	// keeping the cursor on its group by key, else at the nearest position. It runs
140	// after anything that changes what the findings table shows.
141	func (m *Model) refreshGroups() {
142		if m.activeTab != TabCVE || !m.isGrouped() {
143			return
144		}
145		prev, hadPrev := m.groups.Selected()
146		prevCursor := m.groups.Cursor()
147		m.groups.SetItems(visibleGroups(m.groupsAll, m.findingsTable.Visible()))
148		m.groups.Remeasure()
149		if !hadPrev {
150			return
151		}
152		if i := groupIndexByKey(m.groups.Visible(), prev.Key, prevCursor); i >= 0 {
153			m.groups.SetCursor(i)
154		}
155	}
156	
157	// currentGroup is the group an action on a group acts on: the one under the
158	// cursor of the grouped list, or the one the group level shows.
159	func (m Model) currentGroup() (fixGroup, bool) {
160		switch {
161		case m.state == StateGroup && m.openGroup != nil:
162			return groupByKey(m.groupsAll, *m.openGroup)
163		case m.state == StateResults && m.isGrouped():
164			return m.groups.Selected()
165		}
166		return fixGroup{}, false
167	}
168	
169	// groupByKey is the group with key in groups.
170	func groupByKey(groups []fixGroup, key groupKey) (fixGroup, bool) {
171		for _, g := range groups {
172			if g.Key == key {
173				return g, true
174			}
175		}
176		return fixGroup{}, false
177	}
178	
179	// canOpenGroup says whether enter has a group to open.
180	func (m Model) canOpenGroup() shortcut.Availability {
181		if _, ok := m.groups.Selected(); !ok {
182			return shortcut.Unavailable(reasonNoGroupSelected)
183		}
184		return shortcut.Availability{}
185	}
186	
187	// openSelectedGroup opens the group under the cursor: the list of all its
188	// findings, the hidden ones included, since one move closes them all.
189	func (m Model) openSelectedGroup() (tea.Model, tea.Cmd) {
190		if a := m.canOpenGroup(); !a.Enabled() {
191			return m, m.footer.Warn(a.Reason)
192		}
193		g, _ := m.groups.Selected()
194		key := g.Key
195		m.openGroup = &key
196		m.state = StateGroup
197		m.groupTable.SetItems(g.Members)
198		m.groupTable.GotoTop()
199		m.groupTable.Remeasure()
200		return m, nil
201	}
202	
203	// refreshGroupLevel follows a new result in the group level, and in a detail
204	// opened from it: the members are read again by key. A group that is gone takes
205	// the level and the detail with it, back to the grouped list.
206	func (m *Model) refreshGroupLevel() {
207		if m.openGroup == nil {
208			return
209		}
210		g, ok := groupByKey(m.groupsAll, *m.openGroup)
211		if !ok {
212			m.openGroup = nil
213			if m.state == StateGroup || m.state == StateDetails && m.detailsParent == StateGroup {
214				m.state = StateResults
215				m.selectedFinding = nil
216			}
217			return
218		}
219		prev, hadPrev := m.groupTable.Selected()
220		m.groupTable.SetItems(g.Members)
221		m.groupTable.Remeasure()
222		if !hadPrev {
223			return
224		}
225		for i, f := range m.groupTable.Visible() {
226			if sameFinding(f, prev) {
227				m.groupTable.SetCursor(i)
228				return
229			}
230		}
231	}
232	
233	// handleGroupedKey takes the keys the grouped list answers itself. The others
234	// fall through to the results' own handling: the severity tokens, the search and
235	// the tabs drive the findings table, which the list is a view of.
236	func (m Model) handleGroupedKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd, bool) {
237		switch msg.String() {
238		case "enter":
239			next, cmd := m.openSelectedGroup()
240			return next, cmd, true
241		case keymap.Space, writeRemediationKey, keymap.Scan:
242			// They act on one finding, and a group is not one.
243			return m, m.footer.Warn(reasonOpenTheGroup), true
244		case ".", "up", "down", "pgup", "pgdown", "home", "end":
245			return m, m.groups.Update(msg), true
246		}
247		return m, nil, false
248	}
249	
250	// handleGroupState processes input in the group level. Only the keys of its four
251	// shortcuts act: the tabs, the filters and the sort belong to the list behind it.
252	func (m Model) handleGroupState(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
253		switch msg.String() {
254		case "esc":
255			return m.closeGroup()
256		case "enter":
257			f, ok := m.groupTable.Selected()
258			if !ok {
259				return m, m.footer.Warn(reasonNothingToSee)
260			}
261			return m.openDetail(f, StateGroup)
262		case keymap.Copy:
263			return m.copyGroupCommand()
264		case "up", "down", "pgup", "pgdown", "home", "end":
265			return m, m.groupTable.Update(msg)
266		}
267		return m, nil
268	}
269	
270	// closeGroup goes back to the grouped list, on the group that was open.
271	func (m Model) closeGroup() (tea.Model, tea.Cmd) {
272		if m.openGroup != nil {
273			if i := groupIndexByKey(m.groups.Visible(), *m.openGroup, m.groups.Cursor()); i >= 0 {
274				m.groups.SetCursor(i)
275			}
276		}
277		m.state = StateResults
278		m.openGroup = nil
279		return m, nil
280	}
281	
282	// canCopyGroupCommand says whether Y has a group command to copy. In the flat
283	// list there is no group, and the reason says where Y works.
284	func (m Model) canCopyGroupCommand() shortcut.Availability {
285		if m.state == StateResults && !m.isGrouped() {
286			return shortcut.Unavailable(reasonCopyNeedsGroup)
287		}
288		g, ok := m.currentGroup()
289		switch {
290		case !ok:
291			return shortcut.Unavailable(reasonNoGroupSelected)
292		case g.Key.Unfixed:
293			return shortcut.Unavailable(reasonGroupHasNoFix)
294		case g.Command == "":
295			return shortcut.Unavailable(reasonNoGroupCommand)
296		}
297		return shortcut.Availability{}
298	}
299	
300	// copyGroupCommand puts the group's command on the clipboard, whole. It never
301	// runs it, and the write is in the Cmd (Rule 110). The command is plain words by
302	// construction (cveGroups).
303	func (m Model) copyGroupCommand() (tea.Model, tea.Cmd) {
304		if a := m.canCopyGroupCommand(); !a.Enabled() {
305			return m, m.footer.Warn(a.Reason)
306		}
307		g, _ := m.currentGroup()
308		command := g.Command
309		return m, func() tea.Msg {
310			return FixCommandCopiedMsg{Command: command, Err: writeClipboard(command)}
311		}
312	}
313	
314	// groupShortcuts is the group level's column: four keys.
315	func (m Model) groupShortcuts() shortcut.Shortcuts {
316		_, hasMember := m.groupTable.Selected()
317		return []shortcut.Shortcut{
318			{Key: "esc", Description: "Back"},
319			{Key: "enter", Description: "Details", Disabled: !hasMember},
320			{Key: keymap.Copy, Description: "Copy cmd", Disabled: !m.canCopyGroupCommand().Enabled()},
321			{Key: "?", Description: "Help"},
322		}
323	}
324	
325	// groupToggleLabel names the display `g` switches to.
326	func (m Model) groupToggleLabel() string {
327		if m.isGrouped() {
328			return labelListByFinding
329		}
330		return labelGroupByFix
331	}
332	
333	// groupTitle is the group level's title suffix: the cause it lists.
334	func groupTitle(g fixGroup) string {
335		return g.Subject + " " + g.Change
336	}
337	
338	// groupStatus is the footer's sentence about the selected group, a state of the
339	// screen derived on every frame (Rule 128).
340	func (m Model) groupStatus() sharedcomponents.Status {
341		if g, ok := m.currentGroup(); ok {
342			return sharedcomponents.Status{Text: groupSentence(g)}
343		}
344		return sharedcomponents.Status{}
345	}
346	
347	// groupSentence is what the footer says about the selected group.
348	func groupSentence(g fixGroup) string {
349		count := cveCount(len(g.Members))
350		switch {
351		case g.Key.Unfixed:
352			return "No fix published for " + count
353		case g.Target != "":
354			return count + " closed by one move to " + g.Target
355		}
356		// Several candidate versions, none preferred: no single move is promised.
357		_, options, _ := strings.Cut(g.Change, " -> ")
358		if options == "" || options == "none" {
359			return count + ", no single version to move to"
360		}
361		return count + ", fixed in " + options
362	}
363	
364	// cveCount is "1 CVE" or "N CVEs".
365	func cveCount(n int) string {
366		if n == 1 {
367			return "1 CVE"
368		}
369		return strconv.Itoa(n) + " CVEs"
370	}
371	
372	// newGroupsTable is the grouped list's table.
373	func newGroupsTable() datatable.Model[fixGroup] {
374		return datatable.New(datatable.Config[fixGroup]{
375			Columns:    cveGroupColumns(),
376			SortColumn: -1,
377			SelectedStyles: func(g fixGroup) table.Styles {
378				return theme.TableStylesForSeverity(string(g.Severity))
379			},
380		})
381	}
382	
383	// newGroupFindingsTable is the table of the findings of one group: the findings
384	// table's columns, without its tokens and without the File column, which only the
385	// Misconfigurations tab shows.
386	func newGroupFindingsTable(_ *config.Config) datatable.Model[scan.Finding] {
387		t := datatable.New(datatable.Config[scan.Finding]{
388			Columns:        findingColumns(),
389			SortColumn:     -1,
390			SelectedStyles: findingSelectedStyles,
391		})
392		t.SetColumnHidden(fileColumn, true)
393		return t
394	}
